INSERT INTO term (id, entry_id, lang, text, sort_order, term_type, note, origin, review_status) VALUES (5867, 165, 'hy', '«Այո» ասելու համար թարթիր մեկ, «ոչ» ասելու համար՝ երկու անգամ։', 1, 'phrase', NULL, 'sheet', 'unreviewed');
