INSERT INTO term (id, entry_id, lang, text, sort_order, term_type, note, origin, review_status) VALUES (5869, 165, 'zh-Hans', '眨眼一次表示 "是"，两次表示 "否"。', 1, 'phrase', NULL, 'sheet', 'unreviewed');
INSERT INTO term (id, entry_id, lang, text, sort_order, term_type, note, origin, review_status) VALUES (5870, 165, 'zh-Hant', '眨眼一次表示「是」，兩次表示「否」', 1, 'phrase', NULL, 'sheet', 'unreviewed');
INSERT INTO term (id, entry_id, lang, text, sort_order, term_type, note, origin, review_status) VALUES (5871, 165, 'bg', 'За "да" мигни веднъж, за "не" два пъти.', 1, 'phrase', NULL, 'sheet', 'unreviewed');
INSERT INTO term (id, entry_id, lang, text, sort_order, term_type, note, origin, review_status) VALUES (5872, 165, 'ko', '네''면 눈을 한 번, ''아니오''면 두 번 깜빡이세요', 1, 'phrase', NULL, 'sheet', 'unreviewed');
INSERT INTO term (id, entry_id, lang, text, sort_order, term_type, note, origin, review_status) VALUES (5873, 165, 'fa', 'برای بله یک بار و برای خیر دو بار پلک بزن', 1, 'phrase', NULL, 'sheet', 'unreviewed');
INSERT INTO term (id, entry_id, lang, text, sort_order, term_type, note, origin, review_status) VALUES (5874, 165, 'hi', 'हाँ के लिए एक बार और न के लिए दो बार पलकें झपकाएँ', 1, 'phrase', NULL, 'sheet', 'unreviewed');
INSERT INTO term (id, entry_id, lang, text, sort_order, term_type, note, origin, review_status) VALUES (5875, 165, 'pt', 'Pisque uma vez para sim e duas vezes para não', 1, 'phrase', NULL, 'sheet', 'unreviewed');
INSERT INTO term (id, entry_id, lang, text, sort_order, term_type, note, origin, review_status) VALUES (5876, 165, 'sv', 'Blinka en gång för ja och två gånger för nej', 1, 'phrase', NULL, 'sheet', 'unreviewed');
